   873          if (!aFrame.IsARetransmission())
   874          {
   875              aFrame.SetFrameCounter(keyManager.GetMacFrameCounter());
   876              keyManager.IncrementMacFrameCounter();
   877              aFrame.SetKeyId((keyManager.GetCurrentKeySequence() & 0x7f) + 1);
   878          }
   879
   880          break;
   881
   882      case Frame::kKeyIdMode2:
   883      {
   884          const uint8_t keySource[] = {0xff, 0xff, 0xff, 0xff};
   885          aFrame.SetAesKey(sMode2Key);
   886          mKeyIdMode2FrameCounter++;
   887          aFrame.SetFrameCounter(mKeyIdMode2FrameCounter);
   888          aFrame.SetKeySource(keySource);
   889          aFrame.SetKeyId(0xff);
   890          extAddress = static_cast<const ExtAddress *>(&sMode2ExtAddress);
   891          break;
   892      }
   893
   894      default:
   895          assert(false);
   896          break;
   897      }
   898
   899      if (aProcessAesCcm)
   900      {
   901          ProcessTransmitAesCcm(aFrame, extAddress);
   902      }
   903
   904  exit:
   905      return;
   906  }
