   908  void Mac::BeginTransmit(void)
   909  {
   910      otError error                 = OT_ERROR_NONE;
   911      bool    applyTransmitSecurity = true;
   912      bool    processTransmitAesCcm = true;
   913      Frame & sendFrame             = mSubMac.GetTransmitFrame();
   914  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   915      uint8_t timeIeOffset = 0;
   916  #endif
   917
   918      VerifyOrExit(mEnabled, error = OT_ERROR_ABORT);
   919
   920      switch (mOperation)
   921      {
   922      case kOperationActiveScan:
   923          mSubMac.SetPanId(kPanIdBroadcast);
   924          sendFrame.SetChannel(mScanChannel);
   925          SendBeaconRequest(sendFrame);
   926          sendFrame.SetSequence(0);
   927          sendFrame.SetMaxCsmaBackoffs(kMaxCsmaBackoffsDirect);
   928          sendFrame.SetMaxFrameRetries(kMaxFrameRetriesDirect);
   929          break;
   930
   931      case kOperationTransmitBeacon:
   932          sendFrame.SetChannel(mRadioChannel);
   933          SendBeacon(sendFrame);
   934          sendFrame.SetSequence(mBeaconSequence++);
   935          sendFrame.SetMaxCsmaBackoffs(kMaxCsmaBackoffsDirect);
   936          sendFrame.SetMaxFrameRetries(kMaxFrameRetriesDirect);
   937          break;
   938
   939      case kOperationTransmitData:
   940          sendFrame.SetChannel(mRadioChannel);
   941
   942          SuccessOrExit(error = GetNetif().GetMeshForwarder().HandleFrameRequest(sendFrame));
   943
   944          // If the frame is marked as a retransmission, then data sequence number is already set.
   945          if (!sendFrame.IsARetransmission())
   946          {
   947              sendFrame.SetSequence(mDataSequence);
   948          }
   949
   950          break;
   951
   952      case kOperationTransmitOutOfBandFrame:
   953          sendFrame.CopyFrom(*mOobFrame);
   954          applyTransmitSecurity = false;
   955          break;
   956
   957      default:
   958          assert(false);
   959          break;
   960      }
   961
   962  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   963      timeIeOffset = GetTimeIeOffset(sendFrame);
   964      sendFrame.SetTimeIeOffset(timeIeOffset);
   965
   966      if (timeIeOffset != 0)
   967      {
   968          // Transmit security will be processed after time IE content is updated.
   969          processTransmitAesCcm = false;
   970          sendFrame.SetTimeSyncSeq(GetNetif().GetTimeSync().GetTimeSyncSeq());
   971          sendFrame.SetNetworkTimeOffset(GetNetif().GetTimeSync().GetNetworkTimeOffset());
   972      }
   973  #endif
   974
   975      if (applyTransmitSecurity)
   976      {
   977          // Security Processing
   978          ProcessTransmitSecurity(sendFrame, processTransmitAesCcm);
   979      }
   980
   981      mBroadcastTransmitCount = 0;
   982
   983  #if OPENTHREAD_CONFIG_STAY_AWAKE_BETWEEN_FRAGMENTS
   984      if (!mRxOnWhenIdle && !mPromiscuous)
   985      {
   986          mShouldDelaySleep = sendFrame.GetFramePending();
   987          otLogDebgMac("Delay sleep for pending tx");
   988      }
   989  #endif
   990
   991      error = mSubMac.Send();
   992
   993  exit:
   994
   995      if (error != OT_ERROR_NONE)
   996      {
   997          HandleTransmitDone(sendFrame, NULL, OT_ERROR_ABORT);
   998      }
   999  }
