   680                  for (uint8_t j = 0; j < hasRoute->GetNumEntries(); j++)
   681                  {
   682                      hasRouteEntry = hasRoute->GetEntry(j);
   683                      hasRouteEntry->SetRloc(0xfffe);
   684                  }
   685
   686                  break;
   687              }
   688
   689              default:
   690              {
   691                  break;
   692              }
   693              }
   694
   695              // keep stable tlv
   696              cur = cur->GetNext();
   697          }
   698          else
   699          {
   700              // remove temporary tlv
   701              length = sizeof(NetworkDataTlv) + cur->GetLength();
   702              dst    = reinterpret_cast<uint8_t *>(cur);
   703              src    = reinterpret_cast<uint8_t *>(cur->GetNext());
   704              memmove(dst, src, aDataLength - static_cast<size_t>(src - aData));
   705              aPrefix.SetSubTlvsLength(aPrefix.GetSubTlvsLength() - length);
   706              aDataLength -= length;
   707          }
   708      }
