   909  int8_t NetworkData::PrefixMatch(const uint8_t *a, const uint8_t *b, uint8_t aLength)
   910  {
   911      int8_t  rval  = 0;
   912      uint8_t bytes = BitVectorBytes(aLength);
   913      uint8_t diff;
   914
   915      for (uint8_t i = 0; i < bytes; i++)
   916      {
   917          diff = a[i] ^ b[i];
   918
   919          if (diff == 0)
   920          {
   921              rval += 8;
   922          }
   923          else
   924          {
   925              while ((diff & 0x80) == 0)
   926              {
   927                  rval++;
   928                  diff <<= 1;
   929              }
