    73  void Dhcp6Client::UpdateAddresses(void)
    74  {
    75      bool                  found    = false;
    76      bool                  newAgent = false;
    77      otNetworkDataIterator iterator;
    78      otBorderRouterConfig  config;
    79
    80      // remove addresses directly if prefix not valid in network data
    81      for (uint8_t i = 0; i < OT_ARRAY_LENGTH(mIdentityAssociations); i++)
    82      {
    83          IdentityAssociation &ia = mIdentityAssociations[i];
    84
    85          if (ia.mStatus == kIaStatusInvalid || ia.mValidLifetime == 0)
    86          {
    87              continue;
    88          }
    89
    90          found    = false;
    91          iterator = OT_NETWORK_DATA_ITERATOR_INIT;
    92
    93          while ((otNetDataGetNextOnMeshPrefix(&GetInstance(), &iterator, &config)) == OT_ERROR_NONE)
    94          {
    95              if (!config.mDhcp)
    96              {
    97                  continue;
    98              }
    99
   100              if (MatchNetifAddressWithPrefix(ia.mNetifAddress, config.mPrefix))
   101              {
   102                  found = true;
   103                  break;
   104              }
   105          }
   106
   107          if (!found)
   108          {
   109              GetNetif().RemoveUnicastAddress(*static_cast<Ip6::NetifUnicastAddress *>(&ia.mNetifAddress));
   110              mIdentityAssociations[i].mStatus = kIaStatusInvalid;
   111          }
   112      }
   113
   114      // add IdentityAssociation for new configured prefix
   115      iterator = OT_NETWORK_DATA_ITERATOR_INIT;
   116
   117      while (otNetDataGetNextOnMeshPrefix(&GetInstance(), &iterator, &config) == OT_ERROR_NONE)
   118      {
   119          IdentityAssociation *ia = NULL;
   120
   120
   121          if (!config.mDhcp)
   122          {
   123              continue;
   124          }
   125
   126          found = false;
   127
   128          for (uint8_t i = 0; i < OT_ARRAY_LENGTH(mIdentityAssociations); i++)
   129          {
   130              if (mIdentityAssociations[i].mStatus == kIaStatusInvalid)
   131              {
   132                  // record an available ia
   133                  if (ia == NULL)
   134                  {
   135                      ia = &mIdentityAssociations[i];
   136                  }
   137              }
   138              else if (MatchNetifAddressWithPrefix(mIdentityAssociations[i].mNetifAddress, config.mPrefix))
   139              {
   140                  found = true;
   141                  break;
   142              }
   143          }
   144
   145          if (!found)
   146          {
   147              if (ia != NULL)
   148              {
   149                  ia->mPrefixAgentRloc            = config.mRloc16;
   150                  ia->mNetifAddress.mAddress      = config.mPrefix.mPrefix;
   151                  ia->mNetifAddress.mPrefixLength = config.mPrefix.mLength;
   152                  ia->mStatus                     = kIaStatusSolicit;
   153                  ia->mValidLifetime              = 0;
   154                  newAgent                        = true;
   155              }
   156              else
   157              {
   158                  otLogWarnIp6("Insufficient memory for new DHCP prefix");
   159              }
   160          }
   161      }
   162
   163      if (newAgent)
   164      {
   165          Start();
   166      }
   167      else
   168      {
   169          Stop();
   170      }
   171  }
