  1456  void Mle::HandleStateChanged(otChangedFlags aFlags)
  1457  {
  1458      ThreadNetif &netif = GetNetif();
  1459
  1460      VerifyOrExit(mRole != OT_DEVICE_ROLE_DISABLED);
  1461
  1462      if ((aFlags & (OT_CHANGED_IP6_ADDRESS_ADDED | OT_CHANGED_IP6_ADDRESS_REMOVED)) != 0)
  1463      {
  1464          if (!netif.IsUnicastAddress(mMeshLocal64.GetAddress()))
  1465          {
  1466              // Mesh Local EID was removed, choose a new one and add it back
  1467              Random::FillBuffer(mMeshLocal64.GetAddress().mFields.m8 + OT_IP6_PREFIX_SIZE,
  1468                                 OT_IP6_ADDRESS_SIZE - OT_IP6_PREFIX_SIZE);
  1469
  1470              netif.AddUnicastAddress(mMeshLocal64);
  1471              GetNotifier().Signal(OT_CHANGED_THREAD_ML_ADDR);
  1472          }
  1473
  1474          if (mRole == OT_DEVICE_ROLE_CHILD && !IsFullThreadDevice())
  1475          {
  1476              mChildUpdateRequestState = kChildUpdateRequestPending;
  1477              ScheduleMessageTransmissionTimer();
  1478          }
  1479      }
  1480
  1481      if ((aFlags & (OT_CHANGED_IP6_MULTICAST_SUBSRCRIBED | OT_CHANGED_IP6_MULTICAST_UNSUBSRCRIBED)) != 0)
  1482      {
  1483          if (mRole == OT_DEVICE_ROLE_CHILD && !IsFullThreadDevice() && !IsRxOnWhenIdle())
  1484          {
  1485              mChildUpdateRequestState = kChildUpdateRequestPending;
